import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    letters = re.match(r'[A-Z]+', ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Files in archive:")
    for n in names:
        print(" ", n)

    # Map sheet names to xml files via workbook.xml + rels
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root:
        rel_map[rel.get('Id')] = rel.get('Target')
    sheet_files = []
    for sh in wb_root.find('m:sheets', NS):
        rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rel_map.get(rid)
        if target and not target.startswith('/'):
            target = 'xl/' + target
        sheet_files.append((sh.get('name'), target))

    for sname, sfile in sheet_files:
        print(f"\n=== Sheet: {sname} ({sfile}) ===")
        root = ET.fromstring(z.read(sfile))
        sd = root.find('m:sheetData', NS)
        shared_strings = []
        if 'xl/sharedStrings.xml' in names:
            ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in ss_root.findall('m:si', NS):
                shared_strings.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))
        for row in sd.findall('m:row', NS):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = v.text if v is not None else None
                if t == 's' and val is not None:
                    val = shared_strings[int(val)]
                elif t == 'inlineStr':
                    is_el = c.find('m:is', NS)
                    val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if is_el is not None else None
                print(f"  {ref}: {val!r} (type={t})")

