import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    sd = root.find('m:sheetData', NS)

cells = {}
for row in sd.findall('m:row', NS):
    for c in row.findall('m:c', NS):
        v = c.find('m:v', NS)
        if v is not None:
            cells[c.get('r')] = float(v.text)

expense_rows = range(11, 23)
expenses = [(cells.get(f'A{r}'), cells.get(f'B{r}'), cells.get(f'C{r}'))
            for r in expense_rows]

total = sum(c for _, _, c in expenses if c is not None)
print(f"Grand total expenses: {total:,.2f}")

by_cat = {}
for cat, item, amt in expenses:
    if amt is not None:
        by_cat.setdefault(cat, 0.0)
        by_cat[cat] += amt

for cat, amt in by_cat.items():
    print(f"  {cat}: {amt:,.2f}")

